import { useState, useEffect, useCallback, useRef, memo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Search, Filter, X, Grid, List } from 'lucide-react';
import { getPopular, getTrending, searchMulti, img } from '../lib/tmdb';
import type { MediaItem } from '../lib/tmdb';
import MediaCard from '../components/MediaCard';
import { PageSpinner } from '../components/Spinner';
import { useSettings } from '../contexts/SettingsContext';

type MediaType = 'movie' | 'tv';
type SortOption = 'popularity' | 'rating' | 'title' | 'year' | 'recent';

interface Genre {
  id: number;
  name: string;
}

// Memoized genre lists to avoid recreation
const GENRE_LISTS: Record<MediaType, Genre[]> = {
  movie: [
    { id: 28, name: 'Action' }, { id: 12, name: 'Adventure' }, { id: 16, name: 'Animation' },
    { id: 35, name: 'Comedy' }, { id: 80, name: 'Crime' }, { id: 18, name: 'Drama' },
    { id: 10751, name: 'Family' }, { id: 14, name: 'Fantasy' }, { id: 36, name: 'History' },
    { id: 27, name: 'Horror' }, { id: 10402, name: 'Music' }, { id: 9648, name: 'Mystery' },
    { id: 10749, name: 'Romance' }, { id: 878, name: 'Sci-Fi' }, { id: 53, name: 'Thriller' },
    { id: 10752, name: 'War' }, { id: 37, name: 'Western' },
  ],
  tv: [
    { id: 10759, name: 'Action & Adventure' }, { id: 16, name: 'Animation' },
    { id: 35, name: 'Comedy' }, { id: 80, name: 'Crime' }, { id: 99, name: 'Documentary' },
    { id: 18, name: 'Drama' }, { id: 10751, name: 'Family' }, { id: 10762, name: 'Kids' },
    { id: 9648, name: 'Mystery' }, { id: 10763, name: 'News' }, { id: 10764, name: 'Reality' },
    { id: 10765, name: 'Sci-Fi & Fantasy' }, { id: 10766, name: 'Soap' },
    { id: 10767, name: 'Talk' }, { id: 10768, name: 'War & Politics' }, { id: 37, name: 'Western' },
  ],
};

const SORT_OPTIONS = [
  { value: 'popularity', label: 'Popularity' },
  { value: 'rating', label: 'Top Rated' },
  { value: 'title', label: 'A-Z' },
  { value: 'year', label: 'Oldest First' },
  { value: 'recent', label: 'Recently Added' },
];

function BrowseInner() {
  const { type } = useParams<{ type: string }>();
  const navigate = useNavigate();
  const { settings } = useSettings();
  const mediaType = (type === 'movie' || type === 'tv') ? type : 'movie';
  const [items, setItems] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedGenre, setSelectedGenre] = useState<number | null>(null);
  const [sortBy, setSortBy] = useState<SortOption>('popularity');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [loadingMore, setLoadingMore] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const fetchAbortRef = useRef<AbortController | null>(null);

  const genres = GENRE_LISTS[mediaType] || [];

  const fetchItems = useCallback(async (pageNum: number, append = false) => {
    // Cancel previous in-flight request
    fetchAbortRef.current?.abort();
    const controller = new AbortController();
    fetchAbortRef.current = controller;

    setLoading(!append);
    try {
      let data: MediaItem[] = [];

      if (isSearching && searchQuery) {
        setIsSearching(true);
        const searchData = await searchMulti(searchQuery, String(pageNum));
        data = (searchData.results ?? []).filter(
          (r: MediaItem) => r.media_type === mediaType
        );
        setTotalPages(1);
      } else {
        switch (mediaType) {
          case 'movie': {
            const tmdbApiKey = '7335700bba01326857f558c0eea39b8';
            const baseUrl = 'https://api.themoviedb.org/3';
            let url: string;
            if (selectedGenre) {
              url = `${baseUrl}/discover/movie?api_key=${tmdbApiKey}&with_genres=${selectedGenre}&page=${pageNum}&sort_by=popularity.desc`;
            } else {
              url = `${baseUrl}/discover/movie?api_key=${tmdbApiKey}&sort_by=popularity.desc&page=${pageNum}`;
            }
            const res = await fetch(url, { signal: controller.signal });
            const json = await res.json();
            data = json.results || [];
            setTotalPages(json.total_pages || 1);
            break;
          }
          case 'tv': {
            const tmdbApiKey = import.meta.env.VITE_TMDB_API_KEY || '7335700bba01326857f558c0eea39b8';
            const baseUrl = 'https://api.themoviedb.org/3';
            let url: string;
            if (selectedGenre) {
              url = `${baseUrl}/discover/tv?api_key=${tmdbApiKey}&with_genres=${selectedGenre}&page=${pageNum}&sort_by=popularity.desc`;
            } else {
              url = `${baseUrl}/discover/tv?api_key=${tmdbApiKey}&sort_by=popularity.desc&page=${pageNum}`;
            }
            const res = await fetch(url, { signal: controller.signal });
            const json = await res.json();
            data = json.results || [];
            setTotalPages(json.total_pages || 1);
            break;
          }
        }
      }

      if (!append) setItems(data);
      else setItems(prev => [...prev, ...data]);
      setPage(pageNum);
    } catch (error) {
      // Ignore abort errors
      if (error instanceof Error && error.name === 'AbortError') return;
      console.error('Failed to fetch:', error);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [mediaType, isSearching, searchQuery, selectedGenre]);

  useEffect(() => {
    fetchItems(1);
  }, [mediaType, selectedGenre]);

  // Infinite scroll
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !loadingMore && page < totalPages) {
          setLoadingMore(true);
          fetchItems(page + 1, true);
        }
      },
      { threshold: 0.1 }
    );

    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [page, totalPages, loadingMore, fetchItems]);

  // Cleanup abort on unmount
  useEffect(() => {
    return () => {
      fetchAbortRef.current?.abort();
    };
  }, []);

  const handleSearch = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    setItems([]);
    fetchItems(1);
  }, [fetchItems]);

  const handleGenreChange = useCallback((genreId: number | null) => {
    setSelectedGenre(genreId);
    setPage(1);
    setItems([]);
    fetchItems(1);
  }, [fetchItems]);

  const handleSort = useCallback((option: SortOption) => {
    setSortBy(option);
    setItems(prev => [...prev].sort((a, b) => {
      switch (option) {
        case 'rating':
          return (b.vote_average ?? 0) - (a.vote_average ?? 0);
        case 'title':
          return ((a.title || a.name) ?? '').localeCompare((b.title || b.name) ?? '');
        case 'year':
          return ((a.release_date || a.first_air_date) ?? '').localeCompare((b.release_date || b.first_air_date) ?? '');
        case 'recent':
          return (a.popularity ?? 0) - (b.popularity ?? 0);
        default:
          return (b.popularity ?? 0) - (a.popularity ?? 0);
      }
    }));
  }, []);

  const updateViewMode = useCallback((mode: 'grid' | 'list') => {
    setViewMode(mode);
    // localStorage persistence for view mode
    try {
      localStorage.setItem('stinkflix-viewMode', mode);
    } catch { /* storage unavailable */ }
  }, []);

  const activeFilterLabel = isSearching
    ? `Results for "${searchQuery}"`
    : genres.find(g => g.id === selectedGenre)?.name || 'All';

  return (
    <div className="min-h-screen bg-[#0a0a0f] pt-16">
      {/* Header */}
      <div className="sticky top-16 z-40 bg-[#0a0a0f]/95 backdrop-blur-xl border-b border-white/5">
        <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-4">
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" size={18} />
              <input
                ref={searchInputRef}
                type="text"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Search..."
                className="w-full bg-white/5 border border-white/10 text-white placeholder-white/30 rounded-xl pl-10 pr-4 py-2.5 text-sm focus:outline-none focus:border-white/20 transition-all"
              />
            </form>

            {/* Filters toggle */}
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border transition-all ${
                showFilters
                  ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30'
                  : 'bg-white/5 text-white/70 border-white/10 hover:border-white/20'
              }`}
            >
              <Filter size={16} />
              Filters
            </button>

            {/* Sort */}
            <select
              value={sortBy}
              onChange={e => handleSort(e.target.value as SortOption)}
              className="bg-white/5 border border-white/10 text-white text-sm rounded-xl px-4 py-2.5 focus:outline-none focus:border-white/20 cursor-pointer"
            >
              {SORT_OPTIONS.map(opt => (
                <option key={opt.value} value={opt.value} className="bg-[#1a1a2e]">
                  {opt.label}
                </option>
              ))}
            </select>

            {/* View mode */}
            <div className="flex items-center bg-white/5 border border-white/10 rounded-xl overflow-hidden">
              <button
                onClick={() => updateViewMode('grid')}
                className={`p-2.5 transition-all ${
                  viewMode === 'grid' ? 'bg-emerald-500/20 text-emerald-400' : 'text-white/50 hover:text-white'
                }`}
              >
                <Grid size={16} />
              </button>
              <button
                onClick={() => updateViewMode('list')}
                className={`p-2.5 transition-all ${
                  viewMode === 'list' ? 'bg-emerald-500/20 text-emerald-400' : 'text-white/50 hover:text-white'
                }`}
              >
                <List size={16} />
              </button>
            </div>
          </div>

          {/* Genre filters */}
          {showFilters && (
            <div className="mt-3 pt-3 border-t border-white/5">
              <div className="flex items-center gap-2 flex-wrap">
                <button
                  onClick={() => handleGenreChange(null)}
                  className={`px-3 py-1.5 rounded-lg text-sm transition-all ${
                    selectedGenre === null
                      ? 'bg-emerald-500 text-white'
                      : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white'
                  }`}
                >
                  All
                </button>
                {genres.map(genre => (
                  <button
                    key={genre.id}
                    onClick={() => handleGenreChange(genre.id)}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-all ${
                      selectedGenre === genre.id
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white'
                    }`}
                  >
                    {genre.name}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-6">
        <div className="mb-4 flex items-center justify-between">
          <h1 className="text-xl sm:text-2xl font-bold text-white capitalize">
            {mediaType === 'movie' ? 'Movies' : 'TV Shows'}
          </h1>
          <span className="text-white/40 text-sm">{activeFilterLabel}</span>
        </div>

        {loading ? (
          <div className={`grid gap-3 sm:gap-4 ${
            viewMode === 'grid'
              ? 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8'
              : 'grid-cols-1'
          }`}>
            {Array.from({ length: 16 }).map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="bg-white/5 rounded-xl aspect-[2/3]" />
              </div>
            ))}
          </div>
        ) : items.length > 0 ? (
          <>
            <div className={`grid gap-3 sm:gap-4 ${
              viewMode === 'grid'
                ? 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8'
                : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'
            }`}>
              {items.map((item, index) => (
                <MediaCard
                  key={item.id}
                  item={{
                    id: item.id,
                    title: item.title || item.name || 'Untitled',
                    poster_path: item.poster_path,
                    backdrop_path: item.backdrop_path,
                    overview: item.overview,
                    vote_average: item.vote_average,
                    media_type: item.media_type as 'movie' | 'tv' | undefined,
                  }}
                  mediaType={mediaType as MediaType}
                  index={index}
                  viewMode={viewMode}
                />
              ))}
            </div>
            <div ref={loadMoreRef} className="h-4" />
            {loadingMore && (
              <div className="flex justify-center mt-4">
                <div className="w-8 h-8 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin" />
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-24">
            <Search size={56} className="mx-auto text-white/10 mb-5" />
            <p className="text-white/30 text-lg font-medium">No content found</p>
            <p className="text-white/20 text-sm mt-2">Try a different search or filter</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default memo(BrowseInner);